mapper.select:
SELECT 
FROM TBL_BANK_LOAN
WHERE DELETE_FLAG = 0

    AND LOAN_NO LIKE '%' || #{applicationNo} || '%'


    AND LOAN_TYPE = #{loanType}


    AND BANK_ID = #{bankCode}


    AND LOAN_STATUS = #{applicationStatus}


    AND COMPANY_ID = #{companyId}


    AND CURRENCY_CODE = #{currencyCode}

ORDER BY CREATED_TIME DESC

SELECT COUNT(*)
FROM TBL_BANK_LOAN
WHERE DELETE_FLAG = 0

    AND LOAN_TYPE = #{loanType}


    AND BANK_ID = #{bankCode}


    AND LOAN_STATUS = #{applicationStatus}


    AND COMPANY_ID = #{companyId}


    AND CURRENCY_CODE = #{currencyCode}

mapper.update:
UPDATE TBL_BANK_LOAN
SET LOAN_STATUS = #{status}, UPDATED_TIME = SYSDATE
WHERE LOAN_ID = #{loanId}

mapper.select:
SELECT LOAN_TYPE AS "loanType", COUNT(*) AS "count" FROM TBL_BANK_LOAN WHERE DELETE_FLAG = 0
AND COMPANY_ID = #{companyId}
GROUP BY LOAN_TYPE ORDER BY COUNT(*) DESC

SELECT TO_CHAR(CREATED_TIME, 'MM') AS "month", COUNT(*) AS "applicationCount", NVL(SUM(LOAN_AMOUNT), 0) AS "applicationAmount" FROM TBL_BANK_LOAN WHERE DELETE_FLAG = 0 AND CREATED_TIME >= ADD_MONTHS(SYSDATE, -#{months})
AND COMPANY_ID = #{companyId}
GROUP BY TO_CHAR(CREATED_TIME, 'MM') ORDER BY TO_CHAR(CREATED_TIME, 'MM')
